package com.example.distributed_order_processing_system.dto;

import java.math.BigDecimal;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * DTO (Data Transfer Object) = the JSON the client sends to POST /orders.
 * We never expose the database entity directly; the API shape and the DB shape can evolve independently.
 * A Java "record" is an immutable data holder (fields + constructor + getters generated by Java).
 */
public record OrderRequest(

        @NotBlank(message = "productId is required")
        String productId,

        @Min(value = 1, message = "quantity must be at least 1")
        int quantity,

        @NotNull(message = "amount is required")
        @DecimalMin(value = "0.01", message = "amount must be positive")
        BigDecimal amount
) { }
